select c.*
from (SELECT a.id, a.cell, a.local_id, ROW_NUMBER() OVER (PARTITION BY a.cell ORDER BY a.id) AS row_num
from b_wuba_colliding_data_front a
where a.is_deleted = 0
and a.api_code = #{apiCode}
and a.local_id = #{localId}
and a.push_status = 1
and a.status = 1) as c
where c.row_num = 1

    and c.id > #{minId}

order by c.id
limit #{pageSize};

select c.* from (SELECT a.id, a.cell, a.local_id, ROW_NUMBER() OVER (PARTITION BY a.cell ORDER BY a.id) AS row_num from b_wuba_colliding_data_front a left join b_wuba_colliding_data_loop_cycle d on a.cell = d.cell and d.is_deleted = 0 left join b_wuba_colliding_data_second_loop_cycle e on a.cell = e.cell and e.is_deleted = 0 left join b_wuba_colliding_data_rob b on a.cell = b.cell and ((b.create_time >= #{today} and b.create_time < #{tomorrow} ) or (b.package_id in ${highValueIds}) or (b.package_id in ${reavedFileIds})) and b.api_code = #{apiCode} and b.is_deleted = 0 where b.id is null and d.id is null and e.id is null and a.is_deleted = 0 and a.api_code = #{apiCode} and a.local_id = #{localId} and a.push_status = 1 and a.status = 1) as c where c.row_num = 1
and c.id > #{minId}
order by c.id limit #{pageSize};

